(6882096, 1035912, 97225, '<td valign="top">Congratulations, Frank. Lovely work. As <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=96751" rel="nofollow" target="_blank">tanguera </a> mentioned previously, it is very reminiscent of Planet of the Apes.</td>', 'Congratulations, Frank. Lovely work. As  tanguera  mentioned previously, it is very reminiscent of Planet of the Apes.', '2012-10-12 21:11:13.000000', NULL, 0),
